// ora-mod-plan — generated by tools/merge.js: src/ora-mod-plan-*.js plus matching questions from the Oracle role banks (tools/modules.js).
// Oracle Modules — Planning, Manufacturing & Quality. Format: [topic, question, answer, 'B'|'D']
QB["ora-mod-plan"] = (QB["ora-mod-plan"] || []).concat([
["Planning", "What is the difference between Supply Planning, Replenishment Planning and Demand Management in Fusion?", "**Why they ask:** to see if you know the planning suite's pieces.\n\n**Answer:**\n\"Demand Management builds statistical and machine-learning forecasts and the consensus demand plan. Supply Planning is the MRP-style engine: it nets demand against supply across orgs and decides what to make, buy or transfer, constrained or unconstrained. Replenishment Planning handles inventory policies and replenishment for distribution networks, like min-max and safety stock optimization. Sales and Operations Planning ties all of it to the financial plan.\"\n\nTip: Give one line per module. It's a map question, so keep it tidy.", "B", null, null, {"t":1,"f":["Which would a distribution company use most?","Replenishment Planning for stocking locations, fed by Demand Management forecasts, often without full Supply Planning."]}],
["Planning", "What are planning exceptions and how do planners use them?", "**Why they ask:** exceptions are how planners spend their day.\n\n**Answer:**\n\"Exceptions are messages like late replenishment, items below safety stock, excess inventory, past due orders and resource overloads. Planners filter them by priority and act: expedite, reschedule or release. A good setup keeps exceptions actionable. If planners see 5,000 messages, they ignore all of them, so I tune the thresholds until the list is something a planner can work in a day.\"\n\nTip: Make the point about too many exceptions. It's the real problem in most implementations.", "D", null, null, {"t":1,"f":["How do planners avoid drowning in exceptions?","Filter by priority and value, and tune parameters like safety stock so noise exceptions disappear."]}],
["Planning", "What is data collection in Fusion planning?", "**Why they ask:** stale collections are the top cause of bad plans.\n\n**Answer:**\n\"Collections copy reference data, like items, orgs, calendars and sourcing, and transactional data, like on-hand, POs, work orders and sales orders, into the planning data repository. Targeted collections do a full refresh; net change collections bring only what changed. They're scheduled often. If collections are stale, plans and promise dates are wrong, so it's the first thing I check when a plan looks odd.\"\n\nTip: Say it's the first thing you check. It shows real troubleshooting experience.", "D", null, null, {"t":1,"f":["What happens if collections fail before a plan run?","The plan runs on stale data, so recommendations are wrong. I check collection status before every scheduled plan run."]}],
["Manufacturing", "What are work definitions and how do they relate to work orders?", "**Why they ask:** a basic Fusion Manufacturing question.\n\n**Answer:**\n\"A work definition describes how to make an item: the operations, resources, materials and outputs. It's versioned and has a priority when there's more than one. Work orders are created from a work definition, chosen explicitly or by default, and inherit its operations and materials. Changes to a work definition affect new work orders only, not ones already created.\"\n\nTip: Mention that existing work orders don't change. It's a common question from production teams.", "B", null, null, {"f":["What if an item has two work definitions?","The one with the highest priority is used by default, and planning or the user can pick an alternate."]}],
["Manufacturing", "How is material supplied to work orders?", "**Why they ask:** supply types decide how components are issued.\n\n**Answer:**\n\"Each component has a supply type. Push means it's issued manually before or during the job. Assembly pull backflushes it when the assembly is completed. Operation pull backflushes it when an operation is completed. Bulk means it's expensed and not tracked per job, like screws or glue. Phantom means a sub-assembly that's never stocked, so its components are pulled straight into the parent. Supply subinventory and locator default from the item or work definition, and push materials are picked with pick lists or move orders.\"\n\nTip: Give an example for bulk and phantom. They're the ones people mix up.", "D", null, null, {"t":1,"f":["What's the risk of backflushing?","If the BOM is inaccurate, on-hand gets wrong silently. Backflush only works with accurate BOMs and scrap factors."]}],
["Quality", "What is the Quality Issues and Actions (QIA) flow?", "**Why they ask:** quality processes are key in manufacturing and regulated companies.\n\n**Answer:**\n\"Quality issues, or nonconformances, are recorded from receiving, production or customer complaints. They're investigated, and actions are assigned, corrective or preventive. Issues link to items, lots and suppliers. Closure and effectiveness are tracked, and analytics show trends, like one supplier causing most receiving issues.\"\n\nTip: Mention effectiveness checks. A closed action that didn't fix anything is still a problem.", "D", null, null, {"f":["How do quality issues connect to suppliers?","An issue on a received lot can be linked to the supplier, triggering a corrective action request and affecting their scorecard."]}],
["Interview", "What should a planning/manufacturing contractor be ready to discuss?", "**Why they ask:** a preparation question.\n\n**Answer:**\n\"Data foundations, like lead times, BOMs and sourcing, and collections. The plan types and parameters I've set up. Work order execution and costing. Integration with MES and quality systems. And a story where I improved plan accuracy or reduced inventory, with the numbers.\"\n\nTip: Have one improvement story with a number ready. It's what gets remembered.", "B", null, null, {"f":["What planning data problem have you fixed?","Wrong lead times on hundreds of items, causing late POs. Updating them from actual supplier performance cut late replenishment exceptions significantly."]}]
]);

QB['ora-mod-plan'] = (QB['ora-mod-plan'] || []).concat([["Planning","How would you architect supply chain planning for a global company?","**Why they ask:** a senior planning architecture question.\n\n**Answer:**\n\"Demand Management for statistical and ML forecasts by product, customer and region, with a consensus process. Supply Planning for constrained plans across plants and DCs, with a master production schedule for key plants. Sales and Operations Planning linking demand, supply and finance. Replenishment Planning for DC inventory policies. Data comes from Fusion collections and external systems by file, and planning owns the item planning attributes. The cadence is a weekly plan with daily net change. Scenarios support what-if and risk. And it connects to Global Order Promising for customer promises.\"\n\nTip: Mention who owns planning attributes. Data ownership decides whether planning works.","D"],["Planning","What data foundations must be in place before planning can work?","**Why they ask:** planning fails on data more than on software.\n\n**Answer:**\n\"Item attributes: processing and pre- and post-processing lead times, order modifiers, safety stock policy, planning method and make or buy. Accurate BOMs and work definitions. Sourcing rules and assignment sets. Shipping, receiving and manufacturing calendars. Clean demand history, adjusted for returns, promotions and stockouts. Accurate open supply: POs, work orders and transfers. And resource capacities if the plan is constrained. Without these, the plan produces noise and planners won't trust it.\"\n\nTip: End with trust. It's the real cost of bad data.","B"],["Outsourced Manufacturing","How would you model contract manufacturers in Oracle Fusion?","**Why they ask:** outsourcing is common, and modeling it right matters for cost and visibility.\n\n**Answer:**\n\"I'd use Fusion Outsourced Manufacturing, where we own the material and design and the contract manufacturer builds. The CM site is modeled as a contract manufacturing inventory org with work definitions. A purchase order for the CM's service is tied to a work order, and components are shipped to the CM or bought by them on our behalf. The CM reports progress and completions through B2B messages, and we receive the finished goods. Cost is material plus the CM service cost rolled into the assembly. Visibility comes through the supplier portal or B2B.\"\n\nTip: Mention the PO tied to the work order. It's the key modeling idea.","D"],["Manufacturing","How do you architect manufacturing execution between Fusion and MES?","**Why they ask:** most plants run an MES next to the ERP.\n\n**Answer:**\n\"Fusion is the system of record for planning, work orders, costing, inventory and quality records. MES handles shop-floor detail: machine data, operator steps, and in pharma, electronic batch records. Work orders and BOMs or recipes go from Fusion to MES. Consumption, completions, labor and machine time, and quality results come back. I send summaries where ERP doesn't need the detail, near real time for inventory-critical transactions, and I build error handling and WIP reconciliation between the two.\"\n\nTip: Say \"send summaries where detail isn't needed\". Over-integrating is a common mistake.","D"],["Maintenance","How does Oracle Maintenance fit into the SCM architecture?","**Why they ask:** asset-heavy companies need maintenance tied to supply chain.\n\n**Answer:**\n\"Oracle Maintenance manages equipment: assets, work orders, preventive maintenance schedules and meters. Spare parts come from inventory, and purchases go through procurement. Costs go to assets or cost centers, with integration to Fixed Assets. IoT data can trigger condition-based maintenance. The benefits are better uptime and optimized spare parts.\"\n\nTip: Mention IoT-triggered maintenance. It's where the field is going.","D"],["Quality","How would you architect a closed-loop quality process with Oracle?","**Why they ask:** a quality architecture question.\n\n**Answer:**\n\"Inspection plans run at receiving, production and shipping. Failures create nonconformance records, which lead to investigation and CAPA, corrective and preventive actions. Supplier quality uses supplier corrective action requests and scorecards that feed sourcing decisions. When a design or spec changes, a change order in Product Hub carries it. Customer complaints link to lots through genealogy. And analytics show defect trends. The loop is closed when what we learn changes specs, suppliers or processes.\"\n\nTip: Explain what \"closed loop\" means. It's the point of the question.","D"],["Planning","What is S&OP and how would you support it with Oracle?","**Why they ask:** S&OP connects planning to leadership decisions.\n\n**Answer:**\n\"Sales and Operations Planning is a monthly process that aligns demand, supply and finance: demand review, supply review, financial reconciliation, then the executive S&OP meeting. Oracle Sales and Operations Planning in Fusion provides the plans, scenarios, financial views and collaboration. It brings together demand plans, supply plans and EPM financial plans. The outcome is one agreed plan that drives both execution and the finance forecast.\"\n\nTip: Name the four monthly steps. It shows you know the process, not just the tool.","D"],["Planning","Where does AI help most in Fusion planning, and what are the limits?","**Why they ask:** a balanced question about AI.\n\n**Answer:**\n\"AI helps most with machine-learning forecasting and demand sensing, finding anomalies in history, prioritizing and explaining exceptions for planners, and summarizing scenarios for S&OP. The limits are clear: bad master data, like wrong lead times or BOMs, still breaks plans; planners must understand and own the decisions; and explanations matter, because planners won't follow a recommendation they can't understand.\"\n\nTip: Give the limits honestly. Interviewers trust balanced answers more.","D"],["Manufacturing","What is a bill of materials (BOM) and a routing / work definition?","**Why they ask:** a basic manufacturing question.\n\n**Answer:**\n\"A BOM, or item structure, is the list of components and quantities needed to make an item. A routing in EBS, or a work definition in Fusion, is the sequence of operations and resources, machines and labor, with components assigned to the operations where they're used. Together they drive work orders, cost roll-ups and planning. In Fusion, item structures live in Product Hub and work definitions in Manufacturing.\"\n\nTip: Mention where each lives in Fusion. It's a common follow-up.","B",null,null,{"f":["What's the difference between a BOM and a work definition?","The BOM says what goes into the item; the work definition says how it's made, the operations and resources."]}],["Manufacturing","Describe the work order lifecycle in Fusion Manufacturing.","**Why they ask:** a core manufacturing process question.\n\n**Answer:**\n\"A work order is created manually, from planning, or for a sales order. It's released, so components can be picked. Components are issued manually or backflushed. Operations and resources are reported as work is done. The assembly is completed into inventory, with any scrap reported. Then the work order is closed, and Cost Management calculates variances. The statuses go Unreleased, Released, Completed, Closed, and it can also be On Hold or Canceled.\"\n\nTip: Stress closing work orders on time. Late closes delay variances and month-end.","D",null,null,{"f":["What closes a work order?","Completing it, resolving variances and closing it, after which costs are final."]}],["Planning","What is the difference between MRP and min-max planning?","**Why they ask:** to see if you can pick the right method.\n\n**Answer:**\n\"Min-max looks only at on-hand and on-order against fixed minimum and maximum levels. No forecasts, no BOM explosion. MRP, in Fusion Supply Planning, uses demand from forecasts and sales orders, supply from on-hand, POs and work orders, plus BOMs and lead times, to calculate what to make or buy and when, exploding demand down to components. I use min-max for simple, stable items like spares, and MRP for manufactured items and variable demand.\"\n\nTip: Say when you'd use each. That's the real question.","D",null,null,{"f":["What data quality matters most for MRP?","Lead times, BOMs and on-hand accuracy; bad data creates wrong plans."]}],["Planning","How would you approach implementing Fusion Supply Planning?","**Why they ask:** a delivery approach question.\n\n**Answer:**\n\"Data readiness comes first: item planning attributes like lead times, order modifiers and safety stock, accurate BOMs and routings, and sourcing rules. Then collections setup and frequency. Then design plan types, supply plan, replenishment and MPS, and horizons. Then define the exceptions planners will act on. Then pilot one product line and compare the plan's recommendations with what planners would have done. Training focuses on trust: planners need to see why the plan recommends something. And I measure service level, inventory and expedites.\"\n\nTip: Mention the side-by-side comparison in the pilot. It's how trust is built.","D"],["Planning","How do you set safety stock?","**Why they ask:** safety stock is a direct trade-off between service and cash.\n\n**Answer:**\n\"Safety stock can be a fixed quantity, days of supply, or statistical. The statistical method uses demand variability, lead-time variability and a target service level; for example, 95% service uses a z-value of about 1.65. Fusion can calculate safety stock from forecast error. I set higher service levels for A items and critical customers and lower for C items, and review them every quarter, because static safety stock goes stale.\"\n\nTip: Mention the z-value. It shows you understand the math.","D"],["Manufacturing","Discrete vs process manufacturing — what is different in Oracle?","**Why they ask:** industries need different models.\n\n**Answer:**\n\"Discrete manufacturing assembles items from components, like electronics or machinery, using BOMs, work definitions, work orders with operations, and serial tracking. Process manufacturing uses recipes and formulas with yields, by-products and co-products, batch sizes, and potency or grade, like chemicals, food and pharma. Fusion supports both, with process work orders that have multiple outputs. Costing differs too: process manufacturing handles yields and allocates cost across co-products.\"\n\nTip: Mention co-product costing. It's the hard part of process manufacturing.","D"],["Quality","How would you integrate quality inspection into receiving for a regulated company?","**Why they ask:** a regulated-industry design question.\n\n**Answer:**\n\"Regulated items use inspection receipt routing. Inspection plans by item and supplier set sampling, often AQL, and specifications. Received material goes to a quarantine subinventory or status until QA releases it. Failures create nonconformances and supplier corrective action requests. Release uses electronic signatures. And results feed supplier performance scores.\"\n\nTip: Mention quarantine until QA release. It's the core control.","D"],["Planning","How do you get planners to trust a new planning system?","**Why they ask:** adoption decides whether planning projects succeed.\n\n**Answer:**\n\"Clean data first, because wrong lead times destroy trust fast. Then run the new plan in parallel and compare its recommendations with what planners would do, and explain the differences. Show pegging, so planners can see why a planned order exists. Start with the exceptions that matter instead of thousands of messages. Involve senior planners in tuning the parameters. And celebrate quick wins, like expedites avoided or inventory reduced.\"\n\nTip: Involving senior planners is the strongest point. They're the ones others follow.","B"],["Manufacturing","How would you approach a Fusion Manufacturing implementation for a mid-size plant?","**Why they ask:** a delivery approach question.\n\n**Answer:**\n\"First the plant data: work centers, resources, calendars, item structures and work definitions, validated by engineering. Then work order types and execution: manual issue or backflush, and how detailed operation reporting should be, without overdoing it. Then shop-floor devices or tablets, and possibly MES integration. Then costing: standard cost with resource and overhead rates and variance reporting. Quality inspections at key operations. Planned orders from planning becoming work orders. And a pilot on one production line first.\"\n\nTip: Say \"don't overdo operation reporting\". Too much detail slows the shop floor.","D"],["Quality","How does Oracle Quality Management support inspections?","**Why they ask:** a basic quality question.\n\n**Answer:**\n\"Inspection plans define what to check, like a dimension or pH, the sampling, and the acceptance criteria. Inspections are triggered at receiving, at work order operations, or ad hoc in inventory. Results are recorded, and failures can create issues, nonconformances and corrective actions. Rejected material moves to a quarantine status or subinventory. It's integrated with Receiving through inspection routing and with Manufacturing.\"\n\nTip: Give one characteristic example. It makes it concrete.","D"],["Planning","Describe how Supply Planning generates planned orders.","**Why they ask:** a core planning engine question.\n\n**Answer:**\n\"Data collections bring on-hand, POs, work orders, sales orders, forecasts, items and BOMs into the planning repository. A supply plan runs with its options: horizon, organizations, demand schedules and constraints. It nets demand against supply, explodes BOMs, and applies lead times, order modifiers like minimum, maximum and fixed lot multiple, and sourcing rules. It creates planned orders, buy, make or transfer, and recommendations to reschedule in, out or cancel. Planners review them in the Supply Planning work area and release planned orders to execution as requisitions, work orders or transfer orders.\"\n\nTip: End with the release to execution. That's where planning meets the real world.","D"],["Planning","What are sourcing rules, bills of distribution and assignment sets?","**Why they ask:** sourcing drives planning and promising.\n\n**Answer:**\n\"A sourcing rule says where supply comes from for an org or item, for example buy 60% from supplier X and 40% from Y, or transfer from org A, with ranks for priority. A bill of distribution handles sourcing across several orgs, a global source chain. An assignment set assigns sourcing rules at different levels: global, org, category, item, or item-org, and the most specific level wins. Planning, GOP, min-max and automatic requisition sourcing all use them.\"\n\nTip: Say \"the most specific level wins\". It's how you debug sourcing.","D"],["Planning","What is the difference between a forecast and a demand plan?","**Why they ask:** a basic demand planning question.\n\n**Answer:**\n\"A forecast is a prediction of future demand, from history, statistical models or input. A demand plan, in Demand Management, manages forecasts across levels, like product family, region and customer, blends statistical forecasts with sales input into a consensus, and measures forecast accuracy. The approved demand plan feeds the supply plan. And forecast consumption matters: actual sales orders consume the forecast so demand isn't counted twice.\"\n\nTip: Mention forecast consumption. It's what separates a good answer.","D"],["Manufacturing","What is backflushing?","**Why they ask:** a common manufacturing concept with risks.\n\n**Answer:**\n\"Backflushing issues components automatically when an operation or the assembly is reported complete, instead of issuing them beforehand. It's set by the component's supply type: assembly pull at completion, or operation pull at operation completion. It cuts transactions for high-volume, low-value components. The risk is inaccurate on-hand if actual usage differs, for example from scrap, so it needs accurate BOMs and good scrap reporting.\"\n\nTip: Name the risk. It shows judgment.","D"],["Manufacturing","How is work order cost calculated and how are variances recognized?","**Why they ask:** manufacturing cost is a finance and operations meeting point.\n\n**Answer:**\n\"Under standard cost, the assembly is valued at standard, and actual material, resources and overhead are charged to the work order. At close, variances are calculated: material usage, resource efficiency and rate. Under actual or average cost, the assembly cost is the actual cost charged. The accounting is Dr WIP for issues and resources, Cr WIP and Dr Inventory at completion, and variances to variance accounts at close. Closing work orders on time keeps month-end costing clean.\"\n\nTip: End with closing on time. It's the operational lesson.","D"],["Planning","How do you mature a company from spreadsheet planning to integrated business planning?","**Why they ask:** a transformation question.\n\n**Answer:**\n\"In stages. First, clean data and one demand plan in the system, with basic supply planning. Second, constrained supply planning, inventory policies and an S&OP process. Third, integrated business planning with financial plans, scenario modeling and machine-learning forecasting. People and process matter as much as tools: planning roles, meeting cadence and KPIs. And I'd show value at each stage, in forecast accuracy, inventory and service, so the business keeps investing.\"\n\nTip: Say you show value at each stage. It's how transformations keep their funding.","D"],["Planning","How would you integrate commercial and supply planning with finance in an IBP process?","**Why they ask:** IBP is where planning becomes a leadership tool.\n\n**Answer:**\n\"First a common data model: product families, customers and regions, and time buckets that match the financial calendar. Then the chain: demand plan to supply plan to financial projection, revenue, margin, inventory and cash, using standard costs and prices. Gaps against budget are highlighted for executive decisions. Scenario modeling covers things like price changes and capacity limits. EPM integration feeds the financial forecast. And a monthly cadence with clear decision rights.\"\n\nTip: Mention aligning time buckets with the financial calendar. Without it, finance can't use the numbers.","D"]]);
